 *
 * Before reporting anything: please check the changelog first.
 *  - In-repo: ./CHANGELOG.md
 *  - Docs site: https://niko-table.com/changelog
 *
 * Found a bug or have a fix? Open an issue or PR on GitHub so other
 * users (and future LLMs reading this code) benefit:
 * https://github.com/Semkoo/niko-table-registry
 */
import type { RowData } from "@tanstack/react-table"
import { useDataTable } from "../core/data-table-context"
import type { TableDateFilterProps } from "../filters/table-date-filter"
import { TableDateFilter } from "../filters/table-date-filter"
import { useDerivedColumnTitle } from "../hooks/use-derived-column-title"
import { FILTER_VARIANTS } from "../lib/constants"

type DataTableDateFilterProps<TData extends RowData> = Omit<
  TableDateFilterProps<TData>,
  "column" | "title"
> & {
  /**
   * The accessor key of the column to filter (matches column definition)
   */
  accessorKey: keyof TData & string
  /**
   * Optional title override (if not provided, will use column.meta.label)
   */
  title?: string
}

/**
 * A date filter component that automatically connects to the DataTable context
 * and derives the title from column metadata.
 *
 * @example - Auto-detect everything from column metadata
 * const columns: DataTableColumnDef[] = [{ accessorKey: "releaseDate",..., meta: { label: "Release Date" } },...]
 * <DataTableDateFilter accessorKey="releaseDate" />
 *
 * @example - Date range filter
 * <DataTableDateFilter
 *   accessorKey="releaseDate"
 *   multiple
 * />
 *
 * @example - Custom title
 * <DataTableDateFilter
 *   accessorKey="createdAt"
 *   title="Created Date"
 * />
 *
 * @example - Single date selection
 * <DataTableDateFilter
 *   accessorKey="dueDate"
 *   title="Due Date"
 *   multiple={false}
 * />
 */

export function DataTableDateFilter<TData extends RowData>({
  accessorKey,
  title,
  multiple,
  trigger,
  ...props
}: DataTableDateFilterProps<TData>) {
  const { table } = useDataTable<TData>()
  const column = table.getColumn(String(accessorKey))

  const derivedTitle = useDerivedColumnTitle(column, String(accessorKey), title)

  // Auto-set variant in column meta if not already set
  // This allows the auto-filterFn to be applied based on variant
  // Runs synchronously during render (not in an effect) so the variant is set
  // before TableDateFilter receives the column — avoids a deferred render cycle.
  if (column && !column.columnDef.meta?.variant) {
    const meta = (column.columnDef.meta ||= {})
    type ColumnVariant = NonNullable<(typeof meta)["variant"]>
    meta.variant = (
      multiple ? FILTER_VARIANTS.DATE_RANGE : FILTER_VARIANTS.DATE
    ) as ColumnVariant
  }

  // Early return if column not found
  if (!column) {
    console.warn(
      `Column with accessorKey "${accessorKey}" not found in table columns`,
    )
    return null
  }

  return (
    <TableDateFilter
      column={column}
      title={derivedTitle}
      multiple={multiple}
      trigger={trigger}
      {...props}
    />
  )
}

/**
 * @required displayName is required for auto feature detection
 * @see "feature-detection.ts"
 */

DataTableDateFilter.displayName = "DataTableDateFilter"

"use client"

/**
 * niko-table — created by Semir N. (Semkoo, https://github.com/Semkoo) with AI assistance.
 *
 * Before reporting anything: please check the changelog first.
 *  - In-repo: ./CHANGELOG.md
 *  - Docs site: https://niko-table.com/changelog
 *
 * Found a bug or have a fix? Open an issue or PR on GitHub so other
 * users (and future LLMs reading this code) benefit:
 * https://github.com/Semkoo/niko-table-registry
 */

/**
 * A dropdown menu component that allows users to toggle the visibility of table columns.
 * It uses a popover to display a list of columns with checkboxes.
 * Users can search for columns and toggle their visibility.
 */

import { CalendarIcon, XCircle } from "lucide-react"
import * as React from "react"
import type { DateRange } from "react-day-picker"

import { Button } from "@/components/niko-table/primitives/button"
import { Calendar } from "@/components/niko-table/primitives/calendar"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/niko-table/primitives/popover"
import { Separator } from "@/components/ui/separator"
import { formatDate } from "../lib/format"

import type { DataTableColumn } from "../types"
import type { RowData } from "@tanstack/react-table"
type DateSelection = Date[] | DateRange

function getIsDateRange(value: DateSelection): value is DateRange {
  return value && typeof value === "object" && !Array.isArray(value)
}

function parseAsDate(timestamp: number | string | undefined): Date | undefined {
  if (!timestamp) return undefined
  const numericTimestamp =
    typeof timestamp === "string" ? Number(timestamp) : timestamp
  const date = new Date(numericTimestamp)
  return !Number.isNaN(date.getTime()) ? date : undefined
}

function parseColumnFilterValue(value: unknown) {
  if (value === null || value === undefined) {
    return []
  }

  if (Array.isArray(value)) {
    return value.map(item => {
      if (typeof item === "number" || typeof item === "string") {
        return item
      }
      return undefined
    })
  }

  if (typeof value === "string" || typeof value === "number") {
    return [value]
  }

  return []
}

export interface TableDateFilterProps<TData extends RowData> {
  column: DataTableColumn<TData, unknown>
  title?: string
  multiple?: boolean
  trigger?: React.ReactNode
}

export function TableDateFilter<TData extends RowData>({
  column,
  title,
  multiple,
  trigger,
}: TableDateFilterProps<TData>) {
  const columnFilterValue = column.getFilterValue()

  const selectedDates = React.useMemo<DateSelection>(() => {
    if (!columnFilterValue) {
      return multiple ? { from: undefined, to: undefined } : []
    }

    if (multiple) {
      const timestamps = parseColumnFilterValue(columnFilterValue)
      return {
        from: parseAsDate(timestamps[0]),
        to: parseAsDate(timestamps[1]),
      }
    }

    const timestamps = parseColumnFilterValue(columnFilterValue)
    const date = parseAsDate(timestamps[0])
    return date ? [date] : []
  }, [columnFilterValue, multiple])

  const onSelect = React.useCallback(
    (date: Date | DateRange | undefined) => {
      if (!date) {
        column.setFilterValue(undefined)
        return
      }

      if (multiple && !("getTime" in date)) {
        const from = date.from?.getTime()
        const to = date.to?.getTime()
        column.setFilterValue(from || to ? [from, to] : undefined)
      } else if (!multiple && "getTime" in date) {
        column.setFilterValue(date.getTime())
      }
    },
    [column, multiple],
  )

  const onReset = React.useCallback(
    (event: React.MouseEvent) => {
      event.stopPropagation()
      column.setFilterValue(undefined)
    },
    [column],
  )

  const hasValue = React.useMemo(() => {
    if (multiple) {
      if (!getIsDateRange(selectedDates)) return false
      return selectedDates.from || selectedDates.to
    }
    if (!Array.isArray(selectedDates)) return false
    return selectedDates.length > 0
  }, [multiple, selectedDates])

  const formatDateRange = React.useCallback((range: DateRange) => {
    if (!range.from && !range.to) return ""
    if (range.from && range.to) {
      return `${formatDate(range.from)} - ${formatDate(range.to)}`
    }
    return formatDate(range.from ?? range.to)
  }, [])

  const label = React.useMemo(() => {
    if (multiple) {
      if (!getIsDateRange(selectedDates)) return null

      const hasSelectedDates = selectedDates.from || selectedDates.to
      const dateText = hasSelectedDates
        ? formatDateRange(selectedDates)
        : "Select date range"

      return (
        <span className="flex items-center gap-2">
          <span>{title}</span>
          {hasSelectedDates && (
            <>
              <Separator
                orientation="vertical"
                className="mx-0.5 data-[orientation=vertical]:h-4"
              />
              <span>{dateText}</span>
            </>
          )}
        </span>
      )
    }

    if (getIsDateRange(selectedDates)) return null

    const hasSelectedDate = selectedDates.length > 0
    const dateText = hasSelectedDate
      ? formatDate(selectedDates[0])
      : "Select date"

    return (
      <span className="flex items-center gap-2">
        <span>{title}</span>
        {hasSelectedDate && (
          <>
            <Separator
              orientation="vertical"
              className="mx-0.5 data-[orientation=vertical]:h-4"
            />
            <span>{dateText}</span>
          </>
        )}
      </span>
    )
  }, [selectedDates, multiple, formatDateRange, title])

  return (
    <Popover>
      <PopoverTrigger asChild>
        {trigger || (
          <Button variant="outline" size="sm" className="h-8 border-dashed">
            {hasValue ? (
              <div
                role="button"
                aria-label={`Clear ${title} filter`}
                tabIndex={0}
                onClick={onReset}
                className="rounded-sm opacity-70 transition-opacity hover:opacity-100 focus-visible:ring-1 focus-visible:ring-ring focus-visible:outline-none"
              >
                <XCircle className="size-4" />
              </div>
            ) : (
              <CalendarIcon className="size-4" />
            )}
            {label}
          </Button>
        )}
      </PopoverTrigger>
      <PopoverContent className="w-auto p-0" align="start">
        {multiple ? (
          <Calendar
            captionLayout="dropdown"
            mode="range"
            selected={
              getIsDateRange(selectedDates)
                ? selectedDates
                : { from: undefined, to: undefined }
            }
            onSelect={onSelect}
          />
        ) : (
          <Calendar
            captionLayout="dropdown"
            mode="single"
            selected={
              !getIsDateRange(selectedDates) ? selectedDates[0] : undefined
            }
            onSelect={onSelect}
          />
        )}
      </PopoverContent>
    </Popover>
  )
}

/**
 * @required displayName is required for auto feature detection
 * @see "feature-detection.ts"
 */

TableDateFilter.displayName = "TableDateFilter"

"use client"

/**
 * Niko Table's popover primitive, React Aria build. Radix-shaped API
 * (`Popover open onOpenChange`, `PopoverTrigger asChild`, `PopoverContent
 * align side sideOffset`) on shadcn's React Aria `PopoverTrigger` (React Aria
 * `DialogTrigger`, which owns the open state) and `Popover`.
 *
 * `PopoverTrigger asChild` hands the press to its child, which must be the
 * Button primitive (or shadcn's Button), as with shadcn's own trigger.
 */
import * as React from "react"
import { mergeProps } from "react-aria"
import {
  OverlayTriggerStateContext,
  Pressable,
  type Placement,
} from "react-aria-components"

import {
  Popover as PopoverPrimitive,
  PopoverTrigger as PopoverRoot,
} from "@/components/ui/popover"

type Side = "top" | "right" | "bottom" | "left"
type Align = "start" | "center" | "end"

function toPlacement(side: Side, align: Align): Placement {
  if (align === "center") return side
  if (side === "top" || side === "bottom") return `${side} ${align}`
  return `${side} ${align === "start" ? "top" : "bottom"}`
}

function useDataState() {
  const isOpen = React.useContext(OverlayTriggerStateContext)?.isOpen ?? false
  return isOpen ? "open" : "closed"
}

function Popover({
  open,
  defaultOpen,
  onOpenChange,
  children,
}: {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Radix option; React Aria popovers are always modal. */
  modal?: boolean
  children?: React.ReactNode
}) {
  return (
    <PopoverRoot
      isOpen={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
    >
      {children}
    </PopoverRoot>
  )
}

function PopoverTrigger({
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"button"> & { asChild?: boolean }) {
  const state = { "data-state": useDataState() }
  if (asChild && React.isValidElement<object>(children))
    // Slot: the trigger's own props (refs, handlers, classes) merge onto the child.
    return React.cloneElement(
      children,
      mergeProps(children.props, props, state),
    )
  return (
    <Pressable>
      <button type="button" {...props} {...state}>
        {children}
      </button>
    </Pressable>
  )
}

function PopoverContent({
  align = "center",
  side = "bottom",
  sideOffset = 4,
  alignOffset = 0,
  id,
  className,
  children,
  ...props
}: Omit<
  React.ComponentProps<typeof PopoverPrimitive>,
  | "children"
  | "className"
  | "placement"
  | "offset"
  | "crossOffset"
  | "isOpen"
  | "onOpenChange"
  | "triggerRef"
> & {
  align?: Align
  side?: Side
  sideOffset?: number
  alignOffset?: number
  /** Radix puts it on the popup; React Aria's popover takes no `id`. */
  id?: string
  className?: string
  children?: React.ReactNode
}) {
  return (
    <PopoverPrimitive
      {...props}
      placement={toPlacement(side, align)}
      offset={sideOffset}
      crossOffset={alignOffset}
      className={className}
      data-state={useDataState()}
    >
      {id ? (
        <div id={id} className="contents">
          {children}
        </div>
      ) : (
        children
      )}
    </PopoverPrimitive>
  )
}

export { Popover, PopoverContent, PopoverTrigger }

"use client"

/**
 * Niko Table's button primitive, React Aria build: shadcn's React Aria
 * `Button` behind the Radix `Button` API Niko Table calls it with (native
 * `<button>` props, `variant`, `size`, `asChild`).
 *
 * - `onClick` goes to React Aria's `onClick`, its alias of `onPress`: a real
 *   MouseEvent on click and a synthesized click for keyboard and screen-reader
 *   presses, so `stopPropagation()` / `shiftKey` keep working.
 * - `disabled` becomes `isDisabled`.
 * - Everything else (title, tabIndex, role, aria-*, key and mouse handlers) goes
 *   on the `<button>` through React Aria's `render`, as on a native button.
 *   React Aria's Button would drop those attributes and stop key events.
 *
 * Overlay triggers (`PopoverTrigger asChild` and the rest) hand their press to
 * this button, so an `asChild` trigger's child must be this Button (or
 * shadcn's), as with shadcn's own React Aria triggers.
 */
import * as React from "react"
import { mergeProps } from "react-aria"
import type { VariantProps } from "class-variance-authority"

import {
  Button as ButtonPrimitive,
  buttonVariants,
} from "@/components/ui/button"
import { cn } from "@/lib/utils"

type OnPressClick = React.ComponentProps<typeof ButtonPrimitive>["onClick"]

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  if (
    asChild &&
    React.isValidElement<React.HTMLAttributes<HTMLElement>>(children)
  ) {
    // Slot: the child element is the button (e.g. a link styled as one); its
    // own handlers and refs compose with the button's.
    return React.cloneElement(children, {
      ...mergeProps(children.props, { "data-slot": "button" }, props),
      className: cn(
        buttonVariants({ variant, size }),
        className,
        children.props.className,
      ),
    } as React.HTMLAttributes<HTMLElement>)
  }

  const { ref, id, type, slot, disabled, onClick, onMouseDown, ...native } =
    props
  return (
    <ButtonPrimitive
      ref={ref}
      id={id}
      type={type}
      slot={slot}
      variant={variant}
      size={size}
      className={className}
      isDisabled={disabled}
      onClick={onClick as OnPressClick}
      render={domProps => (
        <button
          {...mergeProps(domProps, native)}
          onMouseDown={event => {
            // React Aria's press handler stops every left mousedown; a native
            // button lets it bubble (the grid selects cells on mousedown).
            event.stopPropagation = () => {}
            domProps.onMouseDown?.(event)
            delete (event as Partial<typeof event>).stopPropagation
            onMouseDown?.(event)
          }}
        />
      )}
    >
      {children}
    </ButtonPrimitive>
  )
}

export { Button }

"use client"

/**
 * Niko Table's calendar primitive, React Aria build. The react-day-picker
 * shaped API Niko Table uses (`mode` "single" | "range", `selected` /
 * `onSelect` with JS `Date`s, `defaultMonth`, `autoFocus`) on top of the React
 * Aria shadcn `Calendar` / `RangeCalendar`, converting to and from
 * `@internationalized/date` in the user's time zone.
 */
import {
  fromDate,
  getLocalTimeZone,
  toCalendarDate,
  type CalendarDate,
} from "@internationalized/date"

import {
  Calendar as CalendarPrimitive,
  RangeCalendar,
} from "@/components/ui/calendar"

/** Same shape as react-day-picker's `DateRange`. */
type DateRange = { from: Date | undefined; to?: Date | undefined }

type CalendarProps = {
  className?: string
  /** react-day-picker option; React Aria's calendar always has month/year pickers. */
  captionLayout?: "label" | "dropdown" | "dropdown-months" | "dropdown-years"
  defaultMonth?: Date
  autoFocus?: boolean
  "aria-label"?: string
} & (
  | {
      mode: "single"
      selected?: Date
      onSelect?: (date: Date | undefined) => void
    }
  | {
      mode: "range"
      selected?: DateRange
      onSelect?: (range: DateRange | undefined) => void
    }
)

function toCalendarValue(date: Date | undefined): CalendarDate | null {
  return date ? toCalendarDate(fromDate(date, getLocalTimeZone())) : null
}

function Calendar(props: CalendarProps) {
  const common = {
    className: props.className,
    autoFocus: props.autoFocus,
    "aria-label": props["aria-label"],
    defaultFocusedValue: toCalendarValue(props.defaultMonth) ?? undefined,
  }

  if (props.mode === "range") {
    const { selected, onSelect } = props
    const start = toCalendarValue(selected?.from)
    const end = toCalendarValue(selected?.to)
    return (
      <RangeCalendar
        {...common}
        value={start && end ? { start, end } : null}
        onChange={range =>
          onSelect?.({
            from: range.start.toDate(getLocalTimeZone()),
            to: range.end.toDate(getLocalTimeZone()),
          })
        }
      />
    )
  }

  const { selected, onSelect } = props
  return (
    <CalendarPrimitive
      {...common}
      value={toCalendarValue(selected)}
      onChange={date => onSelect?.(date.toDate(getLocalTimeZone()))}
    />
  )
}

export { Calendar }
